// Deliberately plain acceptance-harness fixture. This is not the ARMGARAGE website or its design.
import {services} from '../../server/qa-armgarage-image/catalog.mjs';
function fixtureApp(catalog,mutation){
 const s={query:'',category:'all',sort:'price-asc',menu:false,dialog:null,detail:null,trigger:null,selected:[],vehicle:'car',urgent:false,booking:null,errors:{},busy:false,success:false};
 const root=document.getElementById('fixture'),attr=id=>'data-testid="'+id+'"',factor={car:1,crossover:1.15,suv:1.3},quote=(ids,v,u)=>{const chosen=catalog.filter(x=>ids.includes(x.id)),subtotal=chosen.reduce((n,x)=>n+x.price,0);return {subtotal,total:Math.round(subtotal*factor[v]*(u?1.2:1))+(mutation==='wrong-calculator'&&subtotal?1:0),minutes:chosen.reduce((n,x)=>n+x.minutes,0)};};
 const esc=v=>String(v??'').replaceAll('&','&amp;').replaceAll('"','&quot;').replaceAll('<','&lt;'),number=n=>n.toLocaleString('ru-RU'),money=(id,n)=>'<output '+attr(id)+' data-amount="'+n+'">'+number(n)+' AMD</output>',options=(values,current)=>values.map(v=>'<option value="'+v+'" '+(v===current?'selected':'')+'>'+v+'</option>').join(''),types=id=>'<select '+attr(id)+'>'+options(['car','crossover','suv'],id==='calc-vehicle'?s.vehicle:s.booking.vehicle)+'</select>';
 const today=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');};
 function openBooking(source){s.trigger=source==='header'?'booking-open':source==='details'?'service-details-'+s.detail:'calc-book';s.booking={name:'',phone:'',car:'',date:'',time:'',comment:'',consent:false,selected:source==='calc'?[...s.selected]:source==='details'?[s.detail]:[],vehicle:source==='calc'?s.vehicle:'car',urgent:source==='calc'?s.urgent:false};s.errors={};s.success=false;s.dialog='booking';render();}
 function close(){s.dialog=null;render();document.querySelector('[data-testid="'+s.trigger+'"]')?.focus();}
 function validate(){const b=s.booking,e={};for(const k of ['name','car'])if(!b[k].trim())e[k]='Заполните поле';const phone=b.phone.replace(/[\s()-]/g,'');if(!/^(?:0\d{8}|\+374\d{8})$/.test(phone))e.phone='Введите телефон';if(!b.selected.length)e.services='Выберите услугу';if(!b.date||(mutation!=='past-date-allowed'&&b.date<today()))e.date='Выберите дату не в прошлом';if(!b.time)e.time='Выберите время';if(!b.consent)e.consent='Требуется согласие';return e;}
 const error=k=>s.errors[k]?'<p '+attr('booking-error-'+k)+' id="error-'+k+'">'+s.errors[k]+'</p>':'',invalid=k=>s.errors[k]?' aria-invalid="true" aria-describedby="error-'+k+'"':'',field=(k,type='text')=>'<label>'+k+'<input '+attr('booking-'+k)+' type="'+type+'" value="'+esc(s.booking[k])+'" '+(type==='date'?'min="'+today()+'"':'')+invalid(k)+'></label>'+error(k);
 function render(){
 const q=quote(s.selected,s.vehicle,s.urgent),filtered=catalog.filter(x=>(mutation==='broken-filter'||x.name.toLowerCase().includes(s.query.trim().toLowerCase()))&&(s.category==='all'||x.category===s.category)).sort((a,b)=>s.sort==='price-desc'?b.price-a.price:a.price-b.price);
 let html='<header><h1>ARMGARAGE</h1><button '+attr('mobile-menu-toggle')+' aria-expanded="'+s.menu+'">Меню</button>'+(s.menu?'<nav '+attr('mobile-menu')+'>Разделы</nav>':'')+'<button '+attr('booking-open')+'>Записаться</button></header><main><section><h2>Услуги</h2><label>Поиск<input '+attr('services-search')+' value="'+esc(s.query)+'"></label><label>Категория<select '+attr('services-category')+'>'+options(['all','diagnostics','maintenance','brakes-suspension','electrical'],s.category)+'</select></label><label>Сортировка<select '+attr('services-sort')+'>'+options(['price-asc','price-desc'],s.sort)+'</select></label><button '+attr('services-reset')+'>Сбросить</button><output '+attr('services-count')+' data-count="'+filtered.length+'">'+filtered.length+'</output>'+(filtered.length?'':'<p '+attr('services-empty')+'>Ничего не найдено</p>')+'<div class="cards">';
 for(const x of filtered)html+='<article '+attr('service-card-'+x.id)+' data-service-id="'+x.id+'" data-price="'+x.price+'" data-minutes="'+x.minutes+'"><h3>'+x.name+'</h3><p '+attr('service-price-'+x.id)+'>'+number(x.price)+' AMD</p><p>'+x.minutes+' мин</p><button '+attr('service-details-'+x.id)+'>Подробнее</button></article>';
 html+='</div></section><section><h2>Калькулятор</h2>'+catalog.map(x=>'<label><input type="checkbox" '+attr('calc-service-'+x.id)+' '+(s.selected.includes(x.id)?'checked':'')+'>'+x.name+'</label>').join('')+'<label>Автомобиль'+types('calc-vehicle')+'</label><label><input type="checkbox" '+attr('calc-urgent')+' '+(s.urgent?'checked':'')+'>Срочно</label>'+money('calc-subtotal',q.subtotal)+money('calc-total',q.total)+'<output '+attr('calc-duration')+' data-minutes="'+q.minutes+'">'+q.minutes+' мин</output>'+(s.selected.length?'':'<p '+attr('calc-empty')+'>Выберите услуги</p>')+'<button '+attr('calc-reset')+'>Сбросить расчёт</button><button '+attr('calc-book')+' '+(s.selected.length?'':'disabled')+'>Записаться с расчётом</button></section></main>';
 if(s.dialog==='service')html+='<section role="dialog" aria-modal="true" aria-label="Услуга" '+attr('service-dialog')+'><h2>'+catalog.find(x=>x.id===s.detail).name+'</h2><button '+attr('service-details-close')+'>Закрыть</button><button '+attr('service-details-book')+'>Записаться на услугу</button></section>';
 if(s.dialog==='booking'){const b=s.booking;html+='<section role="dialog" aria-modal="true" aria-label="Запись" '+attr('booking-dialog')+'><button '+attr('booking-close')+'>Закрыть</button><form novalidate>'+field('name')+field('phone','tel')+field('car')+catalog.map(x=>'<label><input type="checkbox" '+attr('booking-select-service-'+x.id)+' '+(b.selected.includes(x.id)?'checked':'')+'>'+x.name+'</label>').join('')+error('services')+'<label>Тип'+types('booking-vehicle')+'</label><label><input type="checkbox" '+attr('booking-urgent')+' '+(b.urgent?'checked':'')+'>Срочно</label>'+money('booking-total',quote(b.selected,b.vehicle,b.urgent).total)+field('date','date')+'<label>Время<select '+attr('booking-time')+invalid('time')+'>'+options(['','09:00','11:00','14:00','16:00'],b.time)+'</select></label>'+error('time')+'<label>Комментарий<textarea '+attr('booking-comment')+' maxlength="500">'+esc(b.comment)+'</textarea></label><label><input type="checkbox" '+attr('booking-consent')+invalid('consent')+' '+(b.consent?'checked':'')+'>Согласие</label>'+error('consent')+'<button type="submit" '+attr('booking-submit')+' '+(s.busy||s.success?'disabled':'')+'>Отправить демо</button>'+(s.success?'<div role="status" '+attr('booking-success')+'>'+(mutation==='fake-confirmation'?'Запись подтверждена':('Демонстрационная заявка сформирована. Данные не отправлены. Время не подтверждено. '+number(quote(b.selected,b.vehicle,b.urgent).total)+' AMD'))+'</div>':'')+'</form></section>';}
 root.innerHTML=html;if(s.dialog)root.querySelector('[role="dialog"] button')?.focus();
 }
 root.addEventListener('input',e=>{const id=e.target.dataset.testid??'';if(id==='services-search'){s.query=e.target.value;render();}else if(id.startsWith('booking-')&&['name','phone','car','date','comment'].includes(id.slice(8)))s.booking[id.slice(8)]=e.target.value;});
 root.addEventListener('change',e=>{const id=e.target.dataset.testid??'',v=e.target.value,checked=e.target.checked;let changed=true;if(id==='services-category')s.category=v;else if(id==='services-sort')s.sort=v;else if(id==='calc-vehicle')s.vehicle=v;else if(id==='calc-urgent')s.urgent=checked;else if(id.startsWith('calc-service-')){const service=id.slice(13);s.selected=checked?[...new Set([...s.selected,service])]:s.selected.filter(x=>x!==service);}else if(id.startsWith('booking-select-service-')){const service=id.slice(23);s.booking.selected=checked?[...new Set([...s.booking.selected,service])]:s.booking.selected.filter(x=>x!==service);}else if(id==='booking-vehicle')s.booking.vehicle=v;else if(id==='booking-time')s.booking.time=v;else if(id==='booking-urgent')s.booking.urgent=checked;else if(id==='booking-consent')s.booking.consent=checked;else changed=false;if(changed)render();});
 root.addEventListener('click',e=>{const id=e.target.dataset.testid??'';if(id==='mobile-menu-toggle'){s.menu=!s.menu;render();}else if(id==='services-reset'){s.query='';s.category='all';s.sort='price-asc';render();}else if(id.startsWith('service-details-')&&!['service-details-close','service-details-book'].includes(id)){s.detail=id.slice(16);s.trigger=id;s.dialog='service';render();}else if(id==='service-details-close'||id==='booking-close')close();else if(id==='service-details-book')openBooking('details');else if(id==='booking-open')openBooking('header');else if(id==='calc-book')openBooking('calc');else if(id==='calc-reset'){s.selected=[];s.vehicle='car';s.urgent=false;render();}});
 root.addEventListener('submit',e=>{e.preventDefault();if(s.busy||s.success)return;s.errors=validate();if(Object.keys(s.errors).length){render();return;}s.busy=true;render();setTimeout(()=>{if(mutation==='leak-storage')localStorage.setItem('personal',s.booking.name);if(mutation==='outgoing-submit')fetch('/booking-api',{method:'POST',body:JSON.stringify(s.booking)}).catch(()=>{});s.busy=false;s.success=true;render();},250);});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(s.dialog)close();else{s.menu=false;render();}}if(e.key==='Tab'&&s.dialog){const nodes=[...root.querySelectorAll('[role="dialog"] button:not([disabled]),[role="dialog"] input:not([disabled]),[role="dialog"] select:not([disabled]),[role="dialog"] textarea:not([disabled])')];if(e.shiftKey&&document.activeElement===nodes[0]){e.preventDefault();nodes.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===nodes.at(-1)){e.preventDefault();nodes[0].focus();}}});render();
}
export function armgarageFixture(mutation='none'){return [{path:'index.html',text:'<!doctype html><html lang="ru"><meta charset="UTF-8"><title>ARMGARAGE QA fixture</title><style>*{box-sizing:border-box}body{font:16px sans-serif;margin:0;padding:16px}label,output{display:block;padding:4px}input,select,textarea{max-width:100%}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:8px}article{border:1px solid #888;padding:8px}[role=dialog]{position:fixed;inset:12px;background:white;border:2px solid black;padding:12px;overflow:auto}button{padding:8px;margin:4px}</style><div id="fixture"></div><script>('+fixtureApp.toString()+')('+JSON.stringify(services)+','+JSON.stringify(mutation)+')</script></html>'}];}
